"""Required straight lead for explicitly clipped, unattached Bundle ends.

Use the same common planes as the physical Bundle surface, from live source
positions and dimensions. Authored controls, endpoint clips, widths and radii
are unchanged. This supplies a minimum to the generated-lead constructor; it
does not authorize consuming a bend or bypass the cubic curvature certificate.
"""


def _required(g, sources, paths, at):
    index = g.node('GeometryNodeInputIndex', 'Bundle terminal path record').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Live source position').outputs[0]

    def meta(name, kind='INT', record=at):
        return g.sample(paths, g.named('st_path_'+name, kind), record, kind)

    def member(chain):
        selected = g.node('GeometryNodeSeparateGeometry', 'One complete Bundle member path list')
        selected.domain = 'POINT'; g.set(paths, selected.inputs['Geometry'])
        g.set(g.compare(g.named('st_path_chain_index'), chain, kind='INT'), selected.inputs['Selection'])
        ordered = g.node('GeometryNodeSortElements', 'Bundle member semantic Section order')
        ordered.domain = 'POINT'; g.set(selected.outputs['Selection'], ordered.inputs['Geometry'])
        g.set(g.named('st_path_chain_order'), ordered.inputs['Sort Weight'])
        records = ordered.outputs['Geometry']
        size = g.node('GeometryNodeAttributeDomainSize', 'Bundle terminal Section count')
        size.component = 'MESH'; g.set(records, size.inputs['Geometry'])
        count = size.outputs['Point Count']
        ends = []
        for tail, record in ((False, 0), (True, g.math('SUBTRACT', count, 1.))):
            def read(name, kind='INT'):
                return g.sample(records, g.named('st_path_'+name, kind), record, kind)
            forward = read('chain_forward', 'BOOLEAN')
            auth_end = g.compare(forward, tail, kind='INT')
            start, n = read('start'), read('count')
            endpoint = g.math('ADD', start, g.switch(auth_end, 0., g.math('SUBTRACT', n, 1.)))
            neighbor = g.math('ADD', endpoint, g.switch(auth_end, 1., -1.))
            p = g.sample(sources, position, endpoint, 'FLOAT_VECTOR')
            q = g.sample(sources, position, neighbor, 'FLOAT_VECTOR')
            inward = g.vector('NORMALIZE', g.vector('SUBTRACT', q, p))
            clip = g.switch(auth_end, read('clip_start', 'FLOAT'), read('clip_end', 'FLOAT'))
            attached = g.switch(auth_end, read('attached_start', 'BOOLEAN'),
                                read('attached_end', 'BOOLEAN'), 'BOOLEAN')
            width = g.sample(sources, g.named('st_width', 'FLOAT'), read('edge'), 'FLOAT', 'EDGE')
            offset = g.sample(sources, g.named('st_offset', 'FLOAT'), read('edge'), 'FLOAT', 'EDGE')
            ends.append(dict(center=g.vector('ADD', p, g.vector('SCALE', inward, clip)),
                tangent=g.vector('SCALE', inward, -1. if tail else 1.),
                reach=g.math('ADD', g.math('ABSOLUTE', offset), g.math('MULTIPLY', .5, width)),
                valid=g.all(g.compare(count, 0, 'GREATER_THAN', 'INT'),
                    g.compare(clip, 0., 'GREATER_THAN'), g.boolean('NOT', attached)),
                order=read('chain_order')))
        return ends

    own = member(meta('chain_index'))
    other = member(meta('chain_partner'))
    reverse = meta('chain_reversed', 'BOOLEAN')
    own_delta = g.vector('SUBTRACT', own[1]['center'], own[0]['center'])
    other_delta = g.vector('SUBTRACT', other[1]['center'], other[0]['center'])
    axis = g.vector('NORMALIZE', g.vector('ADD', own_delta,
        g.vector('SCALE', other_delta, g.switch(reverse, 1., -1.))))
    enabled = g.all(meta('divided', 'BOOLEAN'), g.compare(meta('chain_partner'), 0, 'GREATER_EQUAL', 'INT'),
                    *(end['valid'] for end in (*own, *other)))
    required = []
    for side, end in enumerate(own):
        partner = g.switch(reverse, other[side]['center'], other[1-side]['center'], 'VECTOR')
        station = g.vector('DOT_PRODUCT', end['center'], axis)
        cut = g.math('MINIMUM' if side else 'MAXIMUM', station, g.vector('DOT_PRODUCT', partner, axis))
        advance = g.vector('DOT_PRODUCT', end['tangent'], axis)
        amount = g.math('DIVIDE', g.math('SUBTRACT', cut, station), advance)
        shear = g.math('ABSOLUTE', g.math('DIVIDE',
            g.vector('DOT_PRODUCT', g.right(end['tangent']), axis), advance))
        distance = g.math('ADD', g.math('ABSOLUTE', amount), g.math('MULTIPLY', end['reach'], shear))
        active = g.all(enabled, g.compare(meta('chain_order'), end['order'], kind='INT'),
                       g.compare(advance, 1e-5, 'GREATER_THAN'))
        # Surface checks require an additional millimetre. A second millimetre
        # leaves room for the subsequent float32 coordinate subtraction.
        required.append(g.switch(active, 0., g.math('ADD', distance, .002)))
    forward = meta('chain_forward', 'BOOLEAN')
    return (g.switch(forward, required[1], required[0]),
            g.switch(forward, required[0], required[1]))


def required(g, sources, paths, at):
    """One shared field group, not a separate solver per Section or fixture."""
    import bpy
    from .path_surface_nodes import _Nodes
    name = 'Prochitecture Streets / Free Bundle terminal lead requirement v1'
    tree = bpy.data.node_groups.get(name)
    if tree is None:
        tree = bpy.data.node_groups.new(name, 'GeometryNodeTree')
        for socket, kind in (('Sources', 'Geometry'), ('Paths', 'Geometry'), ('Path', 'Int')):
            tree.interface.new_socket(name=socket, in_out='INPUT', socket_type='NodeSocket'+kind)
        for socket in ('Start', 'End'):
            tree.interface.new_socket(name=socket, in_out='OUTPUT', socket_type='NodeSocketFloat')
        h = _Nodes(tree)
        inp = h.node('NodeGroupInput', 'Live topology and source dimensions')
        out = h.node('NodeGroupOutput', 'Minimum generated terminal lengths')
        for socket, value in zip(('Start', 'End'), _required(h, inp.outputs['Sources'], inp.outputs['Paths'], inp.outputs['Path'])):
            h.set(value, out.inputs[socket])
    node = g.node('GeometryNodeGroup', 'Required straight room for common Bundle cuts')
    node.node_tree = tree
    for name, value in (('Sources', sources), ('Paths', paths), ('Path', at)):
        g.set(value, node.inputs[name])
    return tuple(node.outputs[name] for name in ('Start', 'End'))
